namespace sv_cffaecfdcb3c469a9593901be294762b.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@* Reusable message input with textarea and submit button *@

<div class="message-input">
    <textarea class="form-control" rows="2" placeholder="@Placeholder"
              @bind="text" @bind:event="oninput"
              @onkeydown="HandleKeyDown"></textarea>
    <button class="btn btn-primary mt-2" @onclick="Submit" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonLabel
    </button>
</div>

@code {
    private string text = string.Empty;

    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Submit();
        }
    }

    private async Task Submit()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var content = text.Trim();
        text = string.Empty;
        await OnSubmit.InvokeAsync(content);
    }
}

@using sv_cffaecfdcb3c469a9593901be294762b.Services

<div class="message-bubble @(IsHighlighted ? "highlighted" : "")"
     @onmouseenter="() => showActions = true"
     @onmouseleave="() => { showActions = false; showEmojiPicker = false; }">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time text-muted">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="badge bg-light text-dark reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <a class="thread-link" href="javascript:void(0)" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </a>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="btn btn-sm btn-outline-secondary" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)" title="Reply in thread">
                💬 Reply
            </button>
            <button class="btn btn-sm btn-outline-secondary" @onclick="ToggleEmojiPicker" title="Add reaction">
                😊 React
            </button>
        </div>

        @if (showEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in commonEmojis)
                {
                    <button class="btn btn-sm emoji-btn" @onclick="() => SelectEmoji(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = { "👍", "❤️", "😂", "🎉", "🤔", "👀" };

    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public bool IsHighlighted { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@using sv_cffaecfdcb3c469a9593901be294762b.Services

<div class="channel-item @(IsActive ? "active" : "")" @onclick="() => OnSelect.InvokeAsync(Channel.Id)">
    <div class="channel-name-row">
        <span class="channel-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="badge bg-primary rounded-pill">@Channel.UnreadCount</span>
        }
    </div>
    <div class="channel-description text-muted text-truncate">@Channel.Description</div>
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<int> OnSelect { get; set; }
}

@using sv_cffaecfdcb3c469a9593901be294762b.Services

<div class="channel-sidebar">
    <h5 class="sidebar-title px-3 py-2">Channels</h5>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelect="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = new();
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@using sv_cffaecfdcb3c469a9593901be294762b.Services
@inject IJSRuntime JS

<div class="message-list" @ref="scrollContainer" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="text-center py-2">
            <span class="spinner-border spinner-border-sm"></span> Loading older messages...
        </div>
    }

    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
    }
</div>

@code {
    private ElementReference scrollContainer;

    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
    {
        return ThreadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

@using sv_cffaecfdcb3c469a9593901be294762b.Services

<div class="message-area">
    <div class="message-area-header border-bottom px-3 py-2">
        <h5 class="mb-0"># @ChannelName</h5>
        <small class="text-muted">@ChannelDescription</small>
    </div>

    <MessageList Messages="Messages"
